-- รุ่นรถที่ใช้ได้กับแพ็กเกจนี้ (จาก legacy master.PackagePatternCarModel)
-- FK ไป packages ผ่าน package_id (เดิม i_pattern) — ตรวจสอบกับข้อมูลจริงแล้วพบว่า
-- i_pattern ในตารางนี้ตรงกับ Package.i_pattern_new (แพ็กเกจที่ตั้งราคาแล้ว) ไม่ใช่ Package.i_pattern
-- (เคยเข้าใจผิดตอนวิเคราะห์ครั้งแรกจากไฟล์ package.sql ที่ยังไม่มีข้อมูลจริงให้ตรวจสอบ)
-- ไม่เก็บ i_usage ซ้ำ เพราะค่าตรงกับ packages.usage_code ของ package_id นั้นอยู่แล้วเสมอ (ข้อมูลซ้ำ)
-- car_model_code เป็นคนละชุดรหัสกับ car_models.code ของเรา (เป็นรหัสกลุ่มรถของระบบเดิม) จึงไม่ FK ไป car_models
CREATE TABLE package_car_models (
    id              BIGINT          GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    package_id      BIGINT          NOT NULL REFERENCES packages(id),
    car_model_code  VARCHAR(30)   NOT NULL,
    car_model_name  VARCHAR(100),
    car_group_code  VARCHAR(10),
    car_group_type  VARCHAR(10),
    active_flag     BOOLEAN       NOT NULL DEFAULT TRUE,
    active_at       TIMESTAMPTZ,
    created_at      TIMESTAMPTZ   NOT NULL,
    created_by      VARCHAR(100)  NOT NULL,
    updated_at      TIMESTAMPTZ   NOT NULL,
    updated_by      VARCHAR(100)  NOT NULL,
    version         BIGINT        NOT NULL DEFAULT 0,

    CONSTRAINT uq_package_car_models_pkg_model UNIQUE (package_id, car_model_code)
);

CREATE INDEX idx_package_car_models_package_id ON package_car_models(package_id);

COMMENT ON TABLE package_car_models IS 'รุ่นรถ (ตามรหัสกลุ่มของระบบเดิม) ที่ใช้ได้กับแต่ละแพ็กเกจ';

-- seed จากข้อมูลจริง legacy master.PackagePatternCarModel (1,860 แถว)
